import type { EndingLine } from './content'
import { MYSTERY_ART_PROMPTS } from './mysteries/artPrompts'

/**
 * Picture prompts for Ecotone's story and encounter cards, keyed by art asset
 * (cards/<id>), plus one per ending storyline still waiting on its renders.
 * Every prompt names only what is visible: who, where, doing what, under what
 * light, from what distance. The player is always the figure in the weathered
 * rain jacket seen from behind, and animals stay ordinary real animals. Mara's cards show her studio and drawings, while her portrait design
 * stays under review (reviewHold.ts). Ported from conductor weird-humboldt
 * art/ART-STANDARD-ROUND-2.yaml and rewritten where a line was figurative.
 */
export const ECOTONE_CARD_ART_PROMPTS: Record<string, string> = {
  'cards/wh-001':
    'A wide view of a small-town plaza with a green lawn and old two-floor wooden storefronts under thin coastal fog. A street performer painted bronze stands frozen on a wooden crate inside a chalk circle, jaw clenched. His shadow on the pavement has a pose of its own, one hand holding up two fingers beside an upturned hat full of coins. A tourist films with a phone held high while a small crowd watches. A figure in a weathered rain jacket stands at the edge of the circle, seen from behind.',
  'cards/wh-002':
    'A ballot kiosk stands on a small-town plaza draped in red, white and blue bunting, its screen glowing blank. On top of it, on a little velvet cushion, sits a single oyster in its half shell, perfectly still. A defeated candidate in a rumpled suit and loosened tie jabs a finger at the machine, while fishers in orange bib overalls and rubber boots lean in with arms crossed, staring at the oyster. A figure in a weathered rain jacket watches from the side under soft fog.',
  'cards/wh-004':
    'A folding table on a town plaza is crowded with mason jars, each full of slowly swirling fog and tied with twine and a blank paper label. One jar glows from inside, holding a tiny night street with a lit bus stop. A fog seller in a long gray overcoat and fedora holds out an open palm. A middle-aged woman in a cardigan reaches for that jar with a wary look. A figure in a weathered rain jacket leans over the table from behind, peering into the little street.',
  'cards/wh-005':
    'An ornate post clock on a small-town plaza has thirteen hour marks on a bare face, its hands pointing straight up as it strikes. Behind it every shop door has a blank square of cardboard hung in the window and blinds drawn. At the curb a delivery van stands with its back doors open, crates of leeks, kale and carrots stacked inside, and a blank ticket tucked under the wiper. The driver scratches his head as pigeons scatter. A figure in a weathered rain jacket looks up at the clock from behind.',
  'cards/wh-007':
    'The inside of an old single-screen movie theater at midnight, every red velvet seat filled, the audience seen from behind as dark heads against a glowing blank screen. Dust drifts through the projector beam. Among the patrons sits one extra shadow wearing an old-fashioned long coat, faintly see-through, already shifting toward an empty seat. In the aisle a young usher in a vest grips her flashlight and counts rows with a worried face. A figure in a weathered rain jacket sits in the back row, seen from behind.',
  'cards/wh-008':
    'On the shallow stage of an old movie theater, in front of a glowing blank screen, a homemade green foam alien prop stands with its arms folded. Propped against it is a small open handbook with one paragraph carefully underlined. The understudy, in a glittery thrift-store costume, holds a prop knife with a broken safety catch, while the director in a headset waves a clipboard. Volunteer crew in black t-shirts stand around with gaffer tape. A figure in a weathered rain jacket watches from the side of the stage under magenta light.',
  'cards/wh-009':
    'An empty old movie theater at night, rows of red velvet seats lit only by the projector. A bright beam full of dust crosses the room, and through it walks a cat-shaped hole in the light, tail raised, casting a dark cat-shaped gap onto the screen. The screen shows a stormy harbor with wind-whipped waves and small fishing boats. Up in the booth window, the projectionist leans out beside stacked film reels. A figure in a weathered rain jacket stands in the aisle, seen from behind.',
  'cards/wh-010':
    'In a darkened old movie theater, a grainy black and white film fills the screen. The actor on it, wearing a weathered rain jacket identical to one worn in the back row, has stopped mid-scene and turned to stare up toward the projection booth. A blank subtitle bar glows beneath him. In the booth window, the projectionist holds a lit lighter near a film reel. In the back row a young adult in a hoodie leans forward, rapt. A figure in a weathered rain jacket sits among the audience, seen from behind.',
  'cards/wh-011':
    'A gravel trailhead at the edge of a redwood forest, with a wooden kiosk and a blank map board. A jogger in running clothes bends over with his hands on his knees, squinting at his smartwatch. Through the ferns and fog, a short way off, stands an identical trailhead with the same kiosk and the same giant redwood, with only ferns and fog between them. Morning sunbeams slant through the canopy. A figure in a weathered rain jacket stands beside the jogger, seen from behind.',
  'cards/wh-013':
    'On a redwood forest trail, a real black-tailed deer stands on all four legs wearing an orange reflective safety vest, ears up, blocking the way. Beside it the creek bank has washed out, the trail edge collapsed into mud and exposed roots. A yellowed blank paper notice is pinned to a wooden post next to an old footbridge. Two hikers have stopped short, and further back along the path a family pushing a stroller is coming closer. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-014':
    'Along the edge of a redwood forest trail, a neat row of wild mushrooms grows on a mossy log, and on every brown cap sits a tiny blank slip of paper. Below them a rusty drainage pipe pokes out of the slope, trickling water down fresh wet mud into a creek that runs cloudy with silt. A trail volunteer in a green vest crouches at the bank holding up a sample jar. A figure in a weathered rain jacket kneels at the trail edge, seen from behind, in soft damp fog.',
  'cards/wh-015':
    'In a redwood clearing at dusk, six folding camp chairs ring a stone fire pit whose gray ash holds a puddle of rainwater. In five of the chairs, faint wisps of fog hang in the shape of seated people leaning toward each other, heads close together. In the sixth chair a real hiker woman with a daypack sits forward, listening with raised eyebrows and pressed lips. An enamel mug lies forgotten in the ferns. A figure in a weathered rain jacket stands at the edge of the circle, seen from behind.',
  'cards/wh-016':
    'In a university lecture hall with tall windows framing redwoods, a tiny grapefruit-sized moon floats above the wooden podium. Its cratered gray face is lit by a borrowed brass desk lamp, and the curved shadow of a partial eclipse is creeping across it. Behind it a chalkboard shows wavy tide diagrams. Students fill the tiered seats with notebooks open, and one skeptical astronomy student has her hand raised high. A figure in a weathered rain jacket sits in the back row, seen from behind.',
  'cards/wh-017':
    'A college dormitory hallway under flickering fluorescent lights, a line of doors running down one side. Between two of them is a stretch of blank painted wall with only the faint outline of a door. Against it someone has set a pair of wet sneakers in a little puddle, and beside them sits a paper bag with a red apple peeking out. A tired resident adviser with a lanyard and clipboard stares at the wall. A figure in a weathered rain jacket stands in the hallway, seen from behind.',
  'cards/wh-018':
    'A university seminar room with rain on the windows and a long wooden table. Three professors sit with coffee cups, and beside them a fourth examiner, a pale, faintly see-through woman in an old-fashioned black academic gown, silver hair pinned up. In front of her lies a thick thesis manuscript bristling with red margin marks. At the end of the room a nervous graduate student stands at a blank projector screen, clutching a laser pointer. A figure in a weathered rain jacket watches from a chair by the wall.',
  'cards/wh-019':
    'On a college sports field ringed by bleachers and redwoods, a student in an oversized foam lumberjack mascot costume, with a giant cartoon human head and plaid shirt, holds a microphone and an open field notebook. Its pages show careful sketches of a strange long-necked creature with a small head and flippers. The costume sags in the heat as the speech booms from the loudspeaker pole. Cheerleaders have stopped mid-routine, and a trainer holds out a water bottle. A figure in a weathered rain jacket watches from the sideline in hazy afternoon light.',
  'cards/wh-020':
    'A university lecture hall on the morning of the first class, its tiered wooden desks empty except for a blank exam booklet already placed on every single one. At the front a teaching assistant hunches over an open laptop, overwhelmed, the chalkboard behind her still clean. In the doorway a crowd of anxious students in hoodies and backpacks holds up their phones, all talking at once. Pale foggy light falls through tall windows framing redwoods. A figure in a weathered rain jacket stands among the students, seen from behind.',
  'cards/wh-022':
    'A rocky beach at low tide in the evening, sea stacks offshore and a rising moon over the water. In a tide pool full of green anemones and sea stars, a large red rock crab raises one claw on a rock, while three small hermit crabs carry tiny blank paper slips stuck to their shells. Empty limpet shells nearby hold little glints of moonlight. A tide-pool volunteer in a fleece vest kneels and gently takes a plastic bucket from a small child in rain boots. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-023':
    'A sandy beach beneath a tall, crumbling bluff in late afternoon light. At the edge of a spent wave, an amber glass bottle with a rolled paper note inside lies in the wet sand at the feet of a figure in a weathered rain jacket, seen from behind and looking down. Up ahead, three families have spread picnic blankets right at the base of the cliff, small children asleep under blankets while a parent sits with arms crossed. Above them, small pebbles and streaks of grit trickle from the overhang.',
  'cards/wh-025':
    'A close view of a piece of frosted green sea glass resting on wet sand among pebbles and small shells. Inside it stands a tiny lighthouse, its lamp slowly turning, throwing a thin amber beam that stretches inland across a trail of footprints. Far behind, out of focus, a woman beachcomber with a canvas bag walks with her head bowed, searching the sand. Sea stacks rise from misty teal water at dusk.',
  'cards/wh-026':
    'A small fishing harbor at dusk beneath a rocky, forested headland, where a small white lighthouse sits on the cliff. Above the headland, in empty fog, a second beacon flashes from bare empty sky above the trees, its glow doubled in the calm water. On the wooden pier, two skippers in rain slickers argue beside stacked crab pots while a harbor pilot in a wool cap turns his back on the light. A figure in a weathered rain jacket stands at the end of the pier, seen from behind.',
  'cards/wh-028':
    'Beside the barnacled pilings of a harbor pier, a real silver salmon pushes its head out of the green water, a tiny blank laminated press badge clipped to its dorsal fin. A figure in a weathered rain jacket crouches at the pier edge, seen from behind, leaning toward it. Further along the pier a tourist aims a camera with a long lens at the ripples. On the rocky shore beyond, a concrete culvert pipe trickles stream water into the harbor under soft coastal fog.',
  'cards/wh-029':
    'At an extreme low tide, the harbor mud lies bare between tall pier pilings, revealing a second wooden dock beneath the first, crusted with barnacles and dripping kelp. Its cleats carry blank mooring tags, and a narrow bare gangway with open sides leads down to it. On the lower dock a tourist clutching a souvenir shell looks up anxiously as the first fingers of water creep back in. A figure in a weathered rain jacket leans over the railing of the upper dock, seen from behind.',
  'cards/wh-030':
    'On a harbor boardwalk swallowed by a dense fog bank, a wooden office counter has unfolded straight out of the mist. Behind it a clerk in a gray uniform and visor raises a rubber stamp over an open ledger of blank pages, his body thinning into fog below the shoulders. A figure in a weathered rain jacket stands at the counter holding out a plastic ID, seen from behind. Just behind them a delivery courier with an insulated bag checks his phone, impatient, beside a brass counter bell.',
  'cards/wh-031':
    'In a small rocky cove, a line of wet bare footprints climbs the beach from the sea, above the reach of the last wave. The prints swerve carefully around shallow sand nests of speckled eggs where tiny plovers huddle. A volunteer in a sun hat holds two lengths of rope stretched across the sand, staring down a group of camera club photographers with long lenses and tripods. A figure in a weathered rain jacket stands at the rope line, seen from behind, as morning fog lifts.',
  'cards/wh-032':
    'At the top of a beach access path, a photographer has set up a tripod, a cash box and a blank wooden sandwich board, with proof prints clipped to a line beside her. Visitors hand over money to look toward the water. Out over the sea the sky has two horizons stacked one above the other, each with its own orange setting sun. Far out on the sand a single visitor stands alone, appearing in both. A figure in a weathered rain jacket waits on the steps, seen from behind.',
  'cards/wh-033':
    'On a windy coastal bluff, a jagged rock face juts out at an odd angle away from the beach. Two visitors have left the marked path, with its low wooden posts and rope, and are stepping toward loose gravel at the crumbling edge, heads tilted, each listening for their own name. Surf crashes far below. A wind-bent cypress leans over the scene. A figure in a weathered rain jacket stays on the path, seen from behind, holding a phone to one ear as fog swirls up the cliff.',
  'cards/wh-034':
    'At the foot of a concrete seawall, a clear tidepool is lit by a single shaft of sun. A small real shrimp perches on a flat rock in that beam of light, facing an audience of sea anemones, sea stars and snails, with a curtain of kelp behind. Up on the seawall, a row of paper cups shivers with every ripple, and a nervous café worker in an apron hurries to trap them under heavy glass jars. String lights glow over the café window. A figure in a weathered rain jacket sits on the wall, seen from behind.',
  'cards/wh-035':
    'A weathered wooden staircase runs down a coastal bluff, and its final step stops short of the sand and ends at the front porch of an ordinary suburban house, sunk in clear green water, its railing, blank doormat and front door wavering below the surface. A porch lamp burns bright underwater while small fish drift past. On the steps behind, a couple holds up a phone, pointing at the door for a photo. A figure in a weathered rain jacket stands on the last dry landing, seen from behind.',
  'cards/wh-036':
    'At a concrete launch ramp on a wide, calm river, a woman rower stands shivering beside her narrow rowing shell. Her two oars lie side by side on the ramp, one dripping river water, the other bone dry. Behind her, her partner is already pushing a second boat into the water, jaw set. Mist hangs over the river and alders, and a steel trail bridge fades into the fog downstream. A figure in a weathered rain jacket approaches with a blanket, seen from behind.',
  'cards/wh-037':
    'On a flat rock at the foot of a steel trail bridge, a tiny three-inch-tall man sits at a desk made of a clam shell, wearing a crisp official uniform and cap. Next to him a real beetle wears a tiny, badly fitting ribbon sash. A neat pile of smooth river pebbles waits beside the desk. A woman in a pocketless raincoat stands puzzled, while her guide dog in harness has already crossed and waits patiently on the bridge. A figure in a weathered rain jacket crouches to look, seen from behind.',
  'cards/wh-038':
    'On a riverside trail at sunset, a blank orange detour board with a painted arrow points off the pavement onto a dirt track. The track leads to a bridge still under construction, its span unfinished above wooden falsework and bundles of rebar, the whole site tinted faded and slightly old. A construction worker in an older-style hard hat stands by the site office trailer, staring at a pair of muddy boots. Behind them, the modern paved trail glows in evening light. A figure in a weathered rain jacket stands at the detour board, seen from behind.',
  'cards/wh-039':
    'Beside a coastal river trail, a committee chair in a sweater vest has set up a folding table and is juggling five clipboards at once, each holding a blank petition sheet. A pale daytime moon hangs in the sky above the river mouth. A few steps away the trail disappears under floodwater, the metal gate standing ankle-deep in reflections. A fisher in waders, rod and tackle box in hand, waits with obvious impatience. A figure in a weathered rain jacket stands between them, seen from behind.',
  'cards/wh-040':
    'On a dry forest trail, a bright yellow kayak hangs upside down from a high cedar limb, strands of kelp dangling from its hull and frayed tie-down straps wrapped around the branch. Seawater drips steadily from it, forming a puddle on the dirt below. A trail crew in hard hats and orange vests has set up a ladder and is revving a chainsaw while one worker points up at the seat. Fog drifts between the trees. A figure in a weathered rain jacket stands at the edge of the trail, seen from behind.',
  'cards/wh-041':
    'On an old town street, an ornate painted Victorian house with turrets and gingerbread trim has sprouted far too many windows, crowded and mismatched across every wall. On the sidewalk in front, the owner in a waistcoat beckons from a wooden ticket booth hung with souvenir keys. Tourists crane their necks toward an upstairs bedroom window. On the front steps, the tenant sits in a cardigan with her arms crossed, unimpressed. A figure in a weathered rain jacket stands on the brick sidewalk, seen from behind, under coastal fog.',
  'cards/wh-042':
    'Inside a cluttered antique shop, the front window holds odd treasures, an old fountain pen on velvet and a top hat under a glass dome. In the middle sits a worn wooden toolbox with a blank paper tag. A woman visitor presses one hand to the glass and points at it, her face tight with worry. Behind a wooden counter an elderly dealer looks up from his ledger. Outside, on the foggy street, a tour group is starting to gather. A figure in a weathered rain jacket stands among the shelves, seen from behind.',
  'cards/wh-044':
    'On an old town street of historic brick buildings, a translucent ghost of an Edwardian gentleman in a bowler hat and long coat stands with his arms folded beside an empty curb space. In the air above it floats a blank parking ticket, tucked under the faint, glassy outline of an antique motorcar windshield. A tow truck driver holds a hook through empty air while a parking officer taps a handheld device. Two wheelchair users wait for the space. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-045':
    'On a bayside boardwalk, a woman holds up a small old printed photograph. It shows this exact street with its blank shopfronts, but under two suns, every building casting a double shadow, and a vintage tram running down the middle of the street. A collector in a camel coat fans out a stack of cash toward her, while an archivist in white cotton gloves reaches for the photograph. Behind them, historic storefronts face the harbor and gulls wheel over the fog. A figure in a weathered rain jacket watches from the side.',
  'cards/wh-046':
    'At a boat ramp on a chilly bay waterfront, a woman in a soaked homemade fish costume climbs out of the gray water, fully clothed and shivering, hugging her arms to her chest. A soggy newspaper with blank pages clings to the front of her costume. Behind her, friends in costumes throw their arms up and cheer, oblivious to her chattering teeth. Volunteers with towels and a medic in a red jacket stand by the dock. A figure in a weathered rain jacket steps forward with a towel, seen from behind.',
  'cards/wh-047':
    'At a waterfront fundraiser, the judges sit behind a skirted table. In the middle, in a glass tank of seawater, a real red octopus has a small square of black cloth draped over its mantle, its arms curling out of the water, each holding up a different blank scorecard. The two human judges beside it share a look. In front of the table, competing crews in homemade costumes wait beside a painted wooden contraption, some amused, some arms crossed. A figure in a weathered rain jacket stands among them, seen from behind.',
  'cards/wh-048':
    'At a waterfront costume contest, an entrant stands inside a huge round white weather balloon costume, face completely hidden, an instrument box and cords dangling beneath. One gloved hand pokes out holding a laminated blank certificate and a neat stack of inspection papers. A volunteer judge with a clipboard and lanyard stares at the paperwork and then at the seamless white balloon. Costumed entrants crowd around the small stage under bunting. A figure in a weathered rain jacket watches from behind in soft pearly fog.',
  'cards/wh-049':
    'On an old town street lined with brick and wooden storefronts, a drumline in plaid flannel shirts and hard hats marches backward, sticks flying over snare and bass drums. Coming straight at them down the same block is the rest of the parade, a brass band and plain colored flags all marching forward. In the crosswalk between them a crossing guard in a yellow vest holds up a blank stop paddle. Spectators crowd the curb under drifting confetti. A figure in a weathered rain jacket stands at the curb, seen from behind.',
  'cards/wh-050':
    'On a bay waterfront after the fundraiser plunge, an empty portable wooden hot tub steams in the fog. Big soap bubbles keep rising from it, each one holding a tiny shimmering picture of a person catching a falling child, a tow truck pulling a car from a ditch, a hand passing a sandwich. Around it, people wrapped in towels and robes over their costumes gaze up in awe. In the middle stands the volunteer who filled it, in a soggy hoodie with a garden hose, hollow-eyed and pale. A figure in a weathered rain jacket comes toward the volunteer holding out a sandwich, seen from behind.',
  'cards/wh-051':
    'Out on open bay water, a floating wooden platform holds oysters arranged in curved tiered rows, one of them ringed by a tiny pearl necklace. A real seagull stands alone on an upturned crate facing them, beside a pile of empty mussel shells and a line of seventeen identical clams. A harbormaster in an orange life vest gestures from a small skiff toward a fishing boat idling in the channel, waiting for room to pass. A figure in a weathered rain jacket watches from a kayak, seen from behind.',
  'cards/wh-052':
    'On a stretch of wet bay shoreline, a large red channel marker buoy lies beached on its side, crusted with barnacles and trailing a rusty chain. Around it, a picket line has been scratched into the sand, and a ring of small blank cardboard squares on sticks stands guard. Just offshore a fishing crew coils lines and starts the engine, one of them pointing toward the shallow shortcut the buoy used to mark. Gulls stand on distant pilings in the fog. A figure in a weathered rain jacket stands at the line, seen from behind.',
  'cards/wh-053':
    'At the bottom of a bay boat ramp sits a homemade rust-orange submarine, riveted together from patches, with bicycle pedals and a chain drive inside a round porthole. Its hatch has a latch only on the outside. Three sleepless mechanics in grease-stained clothes stand around it with coffee thermoses and toolboxes, while a child in a raincoat holds up a clipboard sealed in a plastic bag. The rising tide is already lapping at the trailer wheels. A figure in a weathered rain jacket bends to inspect the hatch, seen from behind.',
  'cards/wh-054':
    'At the tideline of a foggy bay, a retreating wave leaves behind a vintage bicycle lying on the wet sand, chrome gleaming clean and bright. A blank rental tag dangles from its handlebars. Behind it, a double row of rotted old pier stumps marches out into the water and end in open water. A rental clerk in a shop apron and lanyard stands over the bike, hands clasped with worry. A figure in a weathered rain jacket kneels to look at the tag, seen from behind.',
  'cards/wh-056':
    'Under towering redwoods in a quiet park, an old wooden bench is covered with lost childhood things, a small red knitted mitten, a balsa model airplane, a sealed blank envelope, marbles and a faded ribbon. A visitor stands very still in front of it, one hand over her mouth, staring at a single item. Beside the bench a caretaker in a park uniform holds a clipboard, hesitant. Dappled light falls through soft fog in the canopy. A figure in a weathered rain jacket watches from the path, seen from behind.',
  'cards/wh-057':
    'At a small zoo tucked into a redwood park, a human volunteer in a bulky homemade bear mascot costume gives a habitat talk, holding up a habitat chart of painted animal pictures. A zipper seam runs down the back of the padded suit, and the oversized foam head tilts with exhaustion. Children sit cross-legged on the grass, delighted, while a manager in a polo shirt holds up a phone to film. Behind them stretch an enclosure fence and tall redwoods. A figure in a weathered rain jacket stands to one side, seen from behind.',
  'cards/wh-058':
    'On a path at a small zoo among redwoods, a real peacock stands with its tail fanned in brilliant color, a blank paper badge hung on a string around its neck. At its feet lies a pile of confiscated colored pencils and a folded paper warrant. All around, the wooden enclosure boards have been drained to plain white, and the surroundings look faded and gray except for the bird. Two zookeepers in khaki frown beside paint cans and brushes. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-059':
    'On a lawn among tall redwoods, two exhausted grandparents fold a checkered picnic blanket beside a wicker basket and thermos. Around them, family members dressed in clothes from several different decades keep arriving with fresh baskets, children trailing behind. One parent holds a small pill bottle and glances toward a car parked in the distant lot. A delighted photographer raises a camera. Golden late afternoon light slants through fog. A figure in a weathered rain jacket stands at the edge of the lawn, seen from behind.',
  'cards/wh-060':
    'In a redwood park, the trunk of a giant hollow redwood has three small arched wooden doors set into it, each with iron hinges and a blank plaque. The left door has grown a coin slot and a little turnstile. A park ranger in a flat hat holds a clicker counter, puzzled, as a startled visitor steps out of the right-hand door. Down the trail, a teacher leads a school group toward the tree. Shafts of light cut through the fog. A figure in a weathered rain jacket stands before the doors, seen from behind.',
  'cards/wh-062':
    "On a busy casino floor lined with slot machines, one machine's screen shows a hazy vision of a worker in a uniform clocking in for a shift, two coworkers side by side. Glowing mist pours from its payout tray instead of coins. A casino attendant in a vest leans in, startled to recognize the uniform. Next to her a guest in a windbreaker argues and jabs at the machine, demanding what he is owed. Neon light spills across patterned carpet. A figure in a weathered rain jacket sits on a stool, seen from behind.",
  'cards/wh-063':
    'At a river crossing below wooded hills, a middle-aged traveler in a canvas jacket holds out a faded old photograph. It shows wooden bridge decking, an empty vintage car parked on the deck and a small hand-painted wooden post. Beside him, only weathered concrete piers stand in the water where that bridge once was, and a modern bridge crosses just upstream. Willows lean over the gravel bar in warm late afternoon light and river mist. A figure in a weathered rain jacket walks beside him, seen from the side.',
  'cards/wh-064':
    'On the front porch of a small-town house at dusk, a bluegrass musician in overalls plays a banjo, and tiny blue sparks of static jump along its strings. A fiddler plays beside him with eyes closed. Over the hills a single dark storm cloud is gathering in an otherwise clear sky, a faint flicker inside it. Down by the gravel road, an elderly neighbor with a cane points at a roadside culvert clogged with leaves. A figure in a weathered rain jacket stands at the porch steps, seen from behind.',
  'cards/wh-065':
    'In a meadow at the edge of a forest, long potluck tables are covered with casserole dishes and six different pies, each with a blank paper label. The hosts wear long hooded cloaks, faces hidden in shadow, and one very tall guest is pulling its hood lower. At the ranch gate a neighbor lifts a huge telephoto camera lens, while a woman in oven mitts carries hot dishes right past him. String lights hang over the tables in golden afternoon light. A figure in a weathered rain jacket arrives with a covered dish, seen from behind.',
  'cards/wh-066':
    'On a small ridge-top airstrip high in the hills, a sea of fog fills the valleys below under a clear morning sky. On the runway sits a sleek smooth white airplane with bare wings and a seamless nose. Its pilot, in a vintage flight jacket, hands out sandwiches from a wicker basket to a line of passengers in coats. Ground crew in hi-vis vests stand by with clipboards and a fuel hose, looking baffled. A windsock hangs limp by the hangar. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-067':
    'In a muddy hillside pasture, a silver flying saucer sits tilted, half-buried in the mud. A rusty old pickup truck with a homemade tow winch has backed up to it, and two neighbors in flannel and muck boots are already cranking the steel cable taut. Beside the saucer stands its small pilot in a silver flight suit and a helmet with a dark visor, barely taller than the orange warning triangle next to them. Drizzle and fog roll over the hills. A figure in a weathered rain jacket stands back by the fence, seen from behind.',
  'cards/wh-068':
    'Inside a small rural grocery store, a thick personal cloud of fog has drifted in behind a figure in a weathered rain jacket, seen from behind, and settled around the checkout line. Fluorescent lights glow in soft halos through the mist. At the counter a cashier stares in dismay at the scanner display, glowing with old-fashioned blank numerals. Further back, past the produce bins and canned goods shelves, a shopper with a basket gropes through the haze toward the automatic exit doors.',
  'cards/wh-069':
    "On a narrow rural backroad at night, a herd of real cows stands in a neat line across the asphalt, all facing the same way, waiting, a faint green glow hanging in the air in front of them. A delivery van creeps toward them with its headlights on, the driver leaning out the window. A rancher in a cowboy hat stands beside the herd with a flashlight. Beyond a blind bend, the glare of a second truck's headlights is sweeping through the fog. A figure in a weathered rain jacket waves a flashlight at the bend, seen from behind.",
  'cards/wh-070':
    'In a small radio room in a hilltop cabin, a ham-radio operator in headphones leans over a desk crowded with glowing dials, meters and a microphone, scribbling on a notepad. Through the big window, a tall antenna mast stands on the ridge against a deep blue twilight sky, where a strange constellation burns brighter than any other stars. At the door, a neighbor in work clothes and a climbing harness waits with a coffee mug for a forecast. A figure in a weathered rain jacket stands in the room, seen from behind.',
  'cards/wh-071':
    'At the forest edge outside a small rural town, a muddy child-size backpack sits on a tree stump in a foggy clearing. Behind it, half-hidden among the firs, loom two towering shaggy silhouettes, faces lost in the fog, turned toward each other, long arms raised. A smaller shaggy silhouette stands still beside the stump, staring at a television crew, who are hastily packing away a shoulder camera and boom microphone. A neighbor in a fleece vest gestures at them by his pickup. A figure in a weathered rain jacket stands between, seen from behind.',
  'cards/wh-072':
    'Outside a small wooden museum at night, the doorway glows, and through it an open glass display case stands empty on its pedestal. Across the parking lot runs a trail of wet, oversized footprints, ending beside a white plaster footprint cast lying on its back on the asphalt at the end of the trail. A curator in a cardigan sweeps her flashlight along the tracks with a hand pressed to her forehead. Fog drifts under the amber parking lot lamp. A figure in a weathered rain jacket crouches beside the tracks, seen from behind.',
  'cards/wh-073':
    'A wide view of a small clearing in a redwood grove, where a folding table holds neat rows of tiny plaster casts of humanlike footprints, each beside a ruler and an open field notebook. Older researchers in fleece vests and khaki hats bend over the casts with magnifying glasses, and a blank whiteboard leans on an easel. A young researcher sits apart on a mossy log with a closed notebook on their lap. A figure in a weathered rain jacket stands at the edge of the clearing. Fog drifts between the trunks in soft teal and amber light.',
  'cards/wh-074':
    'A wide view of a gravel bar beside a green river under forested hills. On a weathered plank at the water line, pieces of driftwood have been laid out in a long, deliberate pattern of abstract shapes, and a dark flood-debris line marks the boulders behind it. A woman in a work uniform stands well back with her arms crossed and car keys in her hand, while a neighbor points at her. A figure in a weathered rain jacket watches from behind. Morning mist hangs low over the current.',
  'cards/wh-075':
    'A close view of a hidden den entrance tucked under the enormous roots of a redwood at dusk. A smartphone is propped on a mossy stump, its blank screen glowing warm amber, next to an open notebook and a coiled tape measure. Oversized prints are pressed deep into the mud by the doorway, and tufts of dark hair cling to the bark. A neat basket of wild mushrooms sits beside a small lantern and string lights tangled in the roots. Fog settles into the ferns around the empty clearing.',
  'cards/wh-076':
    'A wide view of a mountain highway at night, where a regional bus has pulled onto the gravel shoulder with its hazard lights blinking amber. Beside it stands a blank green mile marker post, faint translucent copies of it repeated along the shoulder. Through the lit windows, passengers turn on one another in argument. The driver stands at the open door checking his watch, and a wheelchair user waits at the lowered ramp. A figure in a weathered rain jacket stands behind them under dark conifers.',
  'cards/wh-077':
    'A wide view of a dark mountain highway at night. On the roadside, a polite middle-aged man in a neat old-fashioned overcoat and flat cap holds out a fan of blank paper gas receipts that glow faintly in the headlights, a small suitcase at his feet. Behind him, another car has pulled into a narrow gravel turnoff beside a steep drop, its hazard lights blinking and its door open. A figure in a weathered rain jacket stands in the foreground with a flashlight. Low fog slides between the conifers.',
  'cards/wh-078':
    'A wide view of an empty gravel lot outside a shuttered country store on a mountain highway at dusk, its windows boarded and its porch faded. At the edge of the lot stands an old pay phone booth with its light still on, the receiver hanging off the hook and swinging on its metal cord as the phone rings. A small notebook and pencil sit on the shelf. A figure in a weathered rain jacket reaches toward the receiver, seen from behind. Forested ridges fade into a teal and purple sky.',
  'cards/wh-079':
    'A wide view of a small highway rest area among conifers, with a cinderblock restroom, picnic tables and a vending machine. A small round silver craft is parked crookedly across two spaces, its hatch open. Tall visitors in silver hooded jumpsuits and mirrored visors stand around, one frowning at an outdoor sink. A caretaker in work coveralls holds a blank white slip of paper beside a corkboard covered in more blank slips, a mop bucket and toolbox at their feet. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-080':
    'A wide view inside an old timber warehouse at the end of a muddy logging road. Towering shelves are packed with cardboard boxes, each with a blank paper tag and claim ticket on a string, and some shelves lean dangerously. Beams of foggy light cut through gaps in the plank walls, full of dust. An older worker in flannel and suspenders holds one small box close to his chest while younger workers steady a shelf. An open ledger sits on a desk. A figure in a weathered rain jacket stands in the doorway.',
  'cards/wh-081':
    'A Victorian shop window on a painted main street in thin morning fog. Behind the glass stands a display mannequin in a yellowed lace bridal gown and a long veil, its head turned toward the sidewalk. A modern paper bus ticket pokes out from under the hem of the veil. Inside the shop a shopkeeper in a gray cardigan raises both hands toward the dress, palms out. Down the street a white wooden church steeple rises over the rooftops, its bell swinging. A figure in a weathered rain jacket stands close to the window, seen from behind, one hand near the glass.',
  'cards/wh-082':
    'A wide view inside a small ornate Victorian theater with red velvet seats and a gilded stage. In the center aisle stands a real dairy cow with a dark red velvet blanket draped across its back, standing on all four legs and facing a row of board members in suits holding papers and curtain swatches. Rain drips through the ceiling into the orchestra pit, splashing onto an empty violinist chair with a violin case on it. On stage, a stage manager in a headset holds a bucket under another leak. A figure in a weathered rain jacket watches from the back row.',
  'cards/wh-083':
    'A wide view inside a Victorian tour house where two carved staircases twist away from the same landing in impossible directions. Doors hang at odd angles on the patterned wallpaper. A tour guide in a period-style dress holds a lantern and gestures urgently to a small group of tourists, while one guest holds up a phone to film. On a side table lies a battered deck of playing cards. A glowing green exit light hangs over an open linen closet full of folded towels. A figure in a weathered rain jacket stands on the lower steps.',
  'cards/wh-084':
    'A wide view of a pie contest on a small-town main street lined with colorful Victorian storefronts. Long tables with checkered cloths hold rows of pies. At the judging table, three empty chairs sit in a row while forks lift slices by themselves and blank white paper squares float above the plates. A young baker in an apron stands firmly beside her lattice-topped blackberry pie with her arms folded. A nervous organizer clutches a clipboard as part of the crowd cheers. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-085':
    'A wide view of a small-town parade on a main street of Victorian storefronts. A float built from cardboard, scrap wood and painted bottle caps carries a detailed miniature of a foggy coastal town, with tiny redwoods, a tiny bay and one tiny figure in a rain jacket caught mid-decision. Beside the float, a young maker in overalls holds a glue gun while an adult man points at her accusingly. Onlookers crowd the curb under crepe paper streamers. A figure in a weathered rain jacket stares at the miniature from behind.',
  'cards/wh-086':
    'A wide view of a wood-paneled lodge conference room with patterned carpet, folding chairs and a long table. Every open door shows the same room again, and again behind it, repeating into the distance. A tired server in a vest carries a tray of coffee cups toward yet another doorway under a glowing green exit light. The hotel manager in a blazer holds up a floor plan, insisting, while attendees with lanyards look around. Fog presses against a window over the river. A figure in a weathered rain jacket stands at the edge.',
  'cards/wh-087':
    'A wide view of a small community hall set up for a hearing, with folding chairs and a panel table. At the microphone stands a very large, burly bearded man with thick dark hair, wearing a tweed cardigan and reading glasses and politely holding a stack of letters. Three neighbors sit in the front row: an older woman in a rain bonnet, a young man with a fence brochure, and a woman knitting. A sample panel of soundproof fencing leans against the wall. A full moon glows in the tall window. A figure in a weathered rain jacket sits at the back.',
  'cards/wh-088':
    'A wide view down a small-town hardware store aisle lined with tall metal shelves and hanging spools of extension cords. In the middle of the floor, cords and sawdust have been arranged into a perfect crop-circle pattern of concentric rings that gives off a faint humming glow. A cashier in a red apron stands rigidly beside a single cable glowing hot and orange. The store owner gestures angrily, while older shoppers peer in from the end of the aisle. A figure in a weathered rain jacket stands at the edge under flickering fluorescent lights.',
  'cards/wh-089':
    'A medium view across the counter of a small-town store. An anxious cashier in a cardigan holds out a long, curling receipt that glows faintly, its paper blank. Beside the old cash register, its drawer open and a coin tray half counted, the store manager stands with arms crossed and a skeptical frown. Stacked behind them are unopened shipping boxes with blank labels. A figure in a weathered rain jacket reaches for the receipt from the near side of the counter. Fog fills the street beyond the rain-streaked window.',
  'cards/wh-090':
    'A wide view of a small wooden volunteer weather station on the bank of a wide, swollen river. An anemometer spins on the roof and a rain gauge stands on a post, while a staff gauge rises from the brown water. Inside the open door, an old printer spits long strips of blank paper that curl in the wind. Volunteers in yellow rain gear hurry about as a resident woman stands holding a printout, looking worried. Dark storm clouds roll in over the cottonwoods. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-091':
    'A wide view of an old-growth redwood forest where one enormous trunk has a fire-hollowed opening. Inside the hollow sits a tiny wooden reception desk with a brass service bell, a number ticket dispenser, a small lamp and an open ledger. A receptionist in a neat cardigan smiles at a short line of visitors dressed in clothes from different centuries. Tourists stay behind a rope on the wooden boardwalk, while a developer in a suit holds up a blank glossy brochure. A figure in a weathered rain jacket stands on the path as fog-lit sunbeams fall between the trunks.',
  'cards/wh-092':
    'A wide view of an old-growth redwood forest thick with fog. Through the haze rises an enormous humanlike silhouette taller than the trees, one long arm pointing farther off-trail. On the public path, witnesses hold their hands at different heights, each describing it differently. Nearby, a tour operator with a small flag leads paying visitors past an orange barrier onto a closed trail, where a restoration crew with shovels and seedlings stands beside erosion netting. A figure in a weathered rain jacket watches from behind on the open path.',
  'cards/wh-093':
    'A wide view of an abandoned roadside attraction under towering redwoods, its painted wooden arch peeling and faded. A crumbling ticket booth has had its window pried open again. In front of it, a perfectly orderly queue of folded blank paper slips floats in midair between rope stanchions, where invisible tourists wait, and fresh footprints appear in the dust. At the gift shop next door, a worried shopkeeper in an apron watches cars squeeze past on the narrow shoulder. A figure in a weathered rain jacket stands at the edge of the gravel.',
  'cards/wh-094':
    'A wide view of a redwood forest floor where a massive fallen log lies across the ferns, its sawn end showing hundreds of tree rings, the two outermost glowing faintly. A volunteer sawyer in a hard hat and orange chaps kneels at the cut face, counting rings with a pin and a loupe, a clipboard at hand. A contractor steps toward the log with a chainsaw, while other volunteers in safety vests stretch caution tape around it. A figure in a weathered rain jacket stands behind them as fog drifts through shafts of light.',
  'cards/wh-095':
    'A wide view along a wooden boardwalk in an old-growth redwood grove. On a huge trunk, a deep fire scar in the furrowed bark forms the faint likeness of a family group: two adults and a small child, the shape shifting as dappled shadows move with the swaying canopy. In the foreground, a figure in a weathered rain jacket, seen from behind, holds open a sketchbook with a rough drawing of the bark. A stranger in a puffy vest raises a large camera toward the trunk. Fog-lit sunbeams fall between the trees.',
  'cards/wh-096':
    'A medium view of a small farm in a rainy river valley. A straw scarecrow on a wooden post, wearing a patched flannel shirt and a battered felt hat, has opened a small notebook with its twine fingers and is pointing at a page. Its burlap face has a stitched mouth and its straw droops with damp. A grower in a muddy canvas jacket rubs the back of his neck sheepishly beside a bale of dry straw. Behind them, an old barn leaks into a bucket. A figure in a weathered rain jacket stands at the edge of the rows.',
  'cards/wh-097':
    'A wide view of a farmhouse porch in a river valley at late afternoon. Two neighbors stand on either side of a porch rail holding clay jugs of homebrew and mason jars, pointing at each other mid-argument: an older man in suspenders and a woman in a barn coat. Behind them, the field appears twice at once as translucent overlapping images, one golden and full of harvest, the other bare and flooded. One neighbor holds a blank sheet toward a community bulletin board. A figure in a weathered rain jacket watches from the steps.',
  'cards/wh-098':
    'A wide view of a garden in a hilly river valley, with hoop greenhouses and rows of potted cannabis plants. An unmarked dark gray helicopter hovers low along the fence line, tracing the boundary stakes, its rotor wash flattening plants and whirling dust and leaves. Sagging power lines run dangerously close to its rotor. Garden workers duck and shield their faces while a grower in a sun hat stares up, and neighbors watch from the fence. A figure in a weathered rain jacket holds a paper map in the foreground.',
  'cards/wh-099':
    'A medium view across an old wooden county clerk counter lined with filing cabinets and ledger books. On the counter, a smooth gray river stone rests on a small embroidered cushion beside a blank will with a ribbon seal. A rancher family in their best clothes stands before it, an older matriarch with folded hands in front while two adult relatives argue behind her. The clerk peers over reading glasses with a rubber stamp in hand. Through the window lies a river and pasture. A figure in a weathered rain jacket waits at the edge.',
  'cards/wh-100':
    'A wide view of the back room of a small-town library, where a circle of mismatched chairs holds a book club in cardigans and shawls, paperbacks in their laps and tea on a side table among candles. Above the circle floats a translucent, stern critic in a tweed jacket, brandishing a red pen while blank pages drift around him. The readers shrink back, one still holding an open book. In the doorway, a librarian with a lanyard stands with her hands on her hips. A figure in a weathered rain jacket sits at the edge of the circle.',
  'cards/wh-101':
    'A wide view of a town plaza with tall palm trees and brick storefronts, set up as the starting line of a kinetic sculpture race. A colorful human-powered sculpture made of welded bicycle frames, painted wooden wheels and a giant clapping-hands contraption sits stalled, its exhausted riders slumped over the handlebars. Spectators clap unevenly around it. A race marshal in a reflective vest checks a watch, a checkered flag under one arm, while a sponsor waves a camera crew closer. A figure in a weathered rain jacket watches from behind in long golden light.',
  'cards/wh-102':
    'A medium view of an archive tent at the kinetic race starting line on a palm-lined town plaza. Old black-and-white race photographs are spread across a folding table with negatives, a loupe and registration ledgers, and the same odd brass-and-wicker sculpture appears in every picture. A volunteer archivist in a cardigan and cotton gloves spreads both hands over the photos as officials approach holding erasers and scissors. Behind them, that very sculpture stands among the entrants with a blank number placard. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-103':
    'A wide view of the judging area at a kinetic sculpture race on a town plaza. One impossible vehicle with glittering fins floats gently above the pavement, its broken axle and wheels dangling in midair. Exhausted welders in leather aprons, masks pushed up, gather underneath with their arms raised in case it falls, while their ordinary, road-scuffed sculptures sit parked nearby. A strange judge in an immaculate pale suit serenely holds up a blank sheet. A figure in a weathered rain jacket watches from behind under soft fog.',
  'cards/wh-104':
    'A wide view of the starting line on a palm-lined town plaza. Six racers in clashing costumes sit on one long human-powered vehicle, their seats linked by a tangle of levers, pulleys and cables, and each pulls a different lever while they argue and laugh. The vehicle lurches forward a few inches. At a registration table beside it, a clerk in a sweater frowns at a blank form with her pen hovering over a single small box. Spectators and other sculptures crowd the plaza. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-105':
    'A wide view of a palm-lined town plaza at the kinetic race start, split down the middle between two times. On the left it is bright noon under a blue sky; on the right it is midnight, with stars and lit street lamps. Two crowds face away from each other, unaware, while colorful sculptures wait on both sides and the launch lane appears twice. A volunteer marshal in a reflective vest spreads her arms to steer a small group of kids in matching shirts out of the lane. A figure in a weathered rain jacket stands on the seam.',
  'cards/wh-106':
    'A wide view of coastal sand dunes, where deep wheel tracks run down a huge, steep drop to a kinetic sculpture with fat balloon tires parked at the bottom. A faint, ghostly afterimage of its descent hangs on the slope. Its exhausted crew, goggles caked with sand, point back up the hill, eager to try again, while a frayed brake cable dangles from the chassis. Spectators line the dune crest among beach grass and rope course markers. A figure in a weathered rain jacket stands beside the vehicle. Fog rolls in from the ocean.',
  'cards/wh-107':
    'A wide view of a sandy kinetic race course through coastal dunes. Across the route stands an elaborate sandcastle city with towers, walls and a tiny town hall flying blank toothpick flags, and on its balcony stands a tiny figure made of driftwood and seashells. A twig toll gate blocks the path beside a pile of seashells. Racers in goggles lean in from their stopped sculpture, while a volunteer in a sun hat kneels and points at pink sand verbena behind a rope fence. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-108':
    'A wide view of a kinetic race course winding through coastal dunes. A large paper course map lies half swallowed by a sliding dune, sand pouring over its edges as three glowing destination markers drift across the page. A mechanic in grease-stained overalls points past a rope habitat fence toward a distant finish arch standing in the protected dune grass. Flagged route markers on poles mark the real course in another direction, and a race marshal hurries over the crest with a whistle. A figure in a weathered rain jacket kneels by the map.',
  'cards/wh-109':
    'A medium view of a judges table set up in coastal dunes during a kinetic race. On the cloth sits a gaudy gift basket covered in sequins, feathers and tinsel, glowing faintly and shedding sparkles, its ribbon fluttering toward the judges. The judges, in silly hats, stare hard in other directions. Before the table stands a young crew in mismatched costumes, their captain with arms crossed, beside a patched vehicle built from donated bicycle wheels and duct tape. A figure in a weathered rain jacket watches from behind as fog drifts off the ocean.',
  'cards/wh-110':
    'A wide view of a kinetic sculpture stalled on a sandy dune course. A rescue crew in shaggy, moss-covered hooded cloaks, their faces hidden in shadow, kneels under the vehicle replacing a broken axle with ordinary wrenches, a jack and an open toolbox, tools passing between gloved hands so quickly they blur. A wheel lies on the sand beside a spare axle. Grateful racers sit on a cooler sharing sandwiches and a thermos, while a sponsor in a polo shirt raises a camera. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-111':
    'A wide view of a concrete boat ramp on a gray bay during a kinetic race water crossing. A giant amphibious sculpture built as a painted teapot with paddle wheels sits planted at the waterline, its wheels dug stubbornly into the mud. Its artist, in a paint-splattered smock, gestures passionately while the skipper in a life vest points at the pontoons. On the seawall, spectators pass dollar bills back and forth, betting on who gets wet first. A figure in a weathered rain jacket stands behind them as gulls wheel in the fog.',
  'cards/wh-112':
    'A wide view of a bay shoreline at the kinetic water crossing. The water near the launch has gone perfectly glassy, and beneath it lies a second upside-down channel; in one patch it is empty, in another faint ghostly racers paddle their sculptures. Two rival crews in life vests stand at the waterline with their amphibious machines, leaning forward to launch first. Far out, the only safety boat follows orange buoys on the real course. A volunteer on the dock holds a radio. A figure in a weathered rain jacket stands on the shore.',
  'cards/wh-113':
    'A wide view of choppy gray bay water at the kinetic crossing. A sleek, iridescent rescue boat flying an unfamiliar starry flag pulls up beside a half-sunk kinetic sculpture, and its crew in crisp silver uniforms hold out clipboards and stacks of blank forms. Meanwhile, local rescue volunteers in kayaks and a small inflatable boat are already throwing a rope to the soaked racer clinging to the sculpture. The tide is rising fast against the pilings. A figure in a weathered rain jacket watches from the end of a dock in the fog.',
  'cards/wh-114':
    'A wide view of a wooden dock on the bay where, for one minute, the tide has traded places with time. Water climbs uphill against the pilings and droplets hang frozen in the air, ripples running backward. On one side, a crate of electrical gear and coiled cables is sliding off the tilted planks as a crew member lunges for it. On the other, a woman in a knit cap kneels at the edge, reaching toward a small glowing snapshot of a boy on a bicycle floating on the surface. A figure in a weathered rain jacket stands between them.',
  'cards/wh-115':
    'A medium view of a folding table on a dock at the end of the kinetic water crossing. A race judge in a sash and blazer fans out six blank ballots, each glowing a different color, beside a small ballot box, while a marshal with a clipboard nods along. Facing them, a soaked mechanic in wet coveralls holds up her scraped, taped knuckles, hair dripping. Behind her, crews stand by their dripping amphibious sculptures, and a few of them are fading into translucent outlines. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-116':
    'A medium view of the awards area on a main street of painted Victorian storefronts. On a draped table stands an ornate brass trophy with a blank plaque, pulsing with a soft red glow, rings of red light rippling outward. A mud-splattered kinetic crew huddles together before it with their arms around each other, uncertain. An announcer in a sequined jacket waits with a microphone as a photographer raises a camera. Their muddy sculpture is parked behind them under string lights. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-117':
    'A wide view down a long main street of painted Victorian storefronts in cold late-afternoon fog. A plain white finish ribbon strung between two poles slides away down the street, leaving motion streaks, while exhausted kinetic racers pedal and push their muddy sculptures after it, one shouting with a fist raised. Back at an empty chalk line on the pavement, a small child in a puffy coat stands holding a homemade foil medal, a folded blanket on the curb beside them. A figure in a weathered rain jacket stands near the child, seen from behind.',
  'cards/wh-118':
    'A medium view at the kinetic race finish on a Victorian main street at dusk. A translucent, ghostly engineer in a leather apron and brass goggles hovers beside a muddy kinetic sculpture, holding out a glowing brass lever while faint blueprint sketches drift in the air around him. An exhausted fabricator in a welding jacket, grease on her cheeks, reaches toward the lever, tempted. Ghostly sails shimmer over the patched sculpture, whose tired riders slump on their seats. A figure in a weathered rain jacket watches from behind under the street lamps.',
  'cards/wh-119':
    'A wide view of the kinetic race finish on a main street of painted Victorian storefronts. Five champions in matching race costumes crowd forward, each wearing a different medal of gold, silver, wood, glass or seashell, all pointing and talking at once with a faint shimmer around them. The crowd faces them eagerly. Ten feet away, a quiet volunteer in a wet orange rescue vest stands alone with a throw rope coiled on her shoulder, damp-haired and overlooked. A figure in a weathered rain jacket stands at the edge, between them, seen from behind.',
  'cards/wh-120':
    'A wide view of the kinetic race finish on a Victorian main street at dusk, where four clean white ballot boxes sit in a row on a long table. A county clerk in a cardigan holds up a hand for quiet. Before the table stand a mechanic still dripping in a soaked race suit, a resident holding up an unpaid paper bill, and a crowd at the back with raised hands. Muddy sculptures line the curb. A figure in a weathered rain jacket holds a blank ballot, seen from behind.',
  'cards/la-baker-01':
    'A wide view of a rugged cove below a steep dirt trail, with two weathered blank wooden boards on a post at its head. Three small camera drones hover above a ring of smooth stones at the surf line, their tiny screens glowing, while beachgoers in jackets turn away. A drone operator in a hoodie stands by a phone on a tripod, controller in hand. A volunteer with a red first-aid kit waves people toward the trail as the incoming tide washes over the stones. A figure in a weathered rain jacket watches from partway down the trail.',
  'cards/la-sohum-01':
    'A wide view of a small rural community arts room at dusk, split down the middle between two different decades: one half bright with modern folding tables and fluorescent light, the other wood-paneled and glowing sepia. On a padded table sits a plain, featureless training mannequin with one hand raised, palm open. Folded sheets and rolled towels wait on the tables. A fully clothed instructor in a fleece vest arranges chairs, a building manager frowns in the doorway with keys, and a student tapes a blank sheet of paper to the wall. A figure in a weathered rain jacket stands at the edge.',
  'cards/la-ferndale-01':
    'A wide view of a tailor shop window on a main street of painted Victorian storefronts. Inside stand four mannequins in clothes from imagined futures: mechanic coveralls with a blank round emblem, a wedding outfit stitched from pale blue flood maps, a graduation gown pieced from yellowed invoices, and a plain coat with every pocket sewn shut. Their heads have turned toward the sidewalk, where a tailor with a measuring tape around his neck, a young apprentice and a developer in a sharp suit holding a checkbook are talking. A figure in a weathered rain jacket watches from behind.',
  'cards/la-cemetery-01':
    'A wide view of a hillside cemetery above a small dairy town, its weathered headstones blank. Just inside the wrought iron gate, three translucent townspeople in everyday clothes sit at a small folding table with blank agenda papers, one holding a rolled ridge map, one a seedling, one a paper invoice. A living groundskeeper with a rake raises a finger to her lips. Beyond a tall clipped hedge, mourners carry flowers among the graves. Fog drifts over the green ridge. A figure in a weathered rain jacket stands at the gate, seen from behind.',
  'cards/fr-mara-01':
    'A borrowed storefront on the short main street of a hill town among oak-covered slopes, with two front doors side by side, one painted red and one painted green. A long strip of plain brown kraft paper hangs half-raised above both doors, one end dangling from a single tack, and an open stepladder stands beneath it. Through the window a reclining tattoo chair, a lamp on a jointed arm and a corkboard of pencil sketches of birds and ferns sit in warm light. On the sidewalk a festival promoter with a lanyard and sunglasses holds out a glossy folder. A figure in a weathered rain jacket stands on the sidewalk between the two doors, seen from behind. Afternoon sun falls on dry golden hills beyond the rooftops.',
  'cards/fr-kit-01':
    'A wide view of a waterfront square lined with old brick warehouses, the harbor and fishing boats behind it. Kit, a Hmong American woman in her late twenties with short asymmetric black hair and paint-splattered mechanic coveralls covered in bright fabric patches, grins and waves a wrench while working on a parade of scrap sculptures: an elephant built from a bent bicycle wheel, a jellyfish made from a broken umbrella with ribbon tentacles, and one plain broken umbrella. Volunteers carry scrap past wagons. A figure in a weathered rain jacket stands across the square.',
  'cards/fr-juniper-01':
    'A wide view of a dirt trail in an urban redwood park, where a handmade blank square of cardboard stands on a stake beside a young sapling. Juniper, a curvy young woman with messy auburn hair, a green ribbon and tiny ferns tucked in it, freckles, a layered thrift-store sweater and a long patchwork skirt, listens and nods with a notebook in hand. Around her stand a trail crew with shovels and a wheelbarrow and an older walker with a rolling walker. A blue jay watches from a branch. A figure in a weathered rain jacket stands at the edge of the group.',
  'cards/fr-cedar-01':
    'A wide view of a cluttered shed in a rural river valley, piled waist-deep with old tube radios, coiled coax cable and car batteries, a small lattice antenna tower rising beside it. Cedar, a rugged man in his thirties of mixed Latino heritage with warm light brown skin, dark hair, short stubble, a worn trucker cap and an oil-stained canvas work jacket, looks up from the gear with a wry smile. His father holds a battered logger toolbox and his mother a stack of meeting notes. A curious goat peeks through the doorway. A figure in a weathered rain jacket stands at the door.',
  'cards/fr-assembly-01':
    'A wide view of a waterfront where an old brick warehouse has its roll-up door open on a community repair workshop. Beside it, a long potluck table holds steaming pots of soup, mismatched bowls and loaves of bread, with a blank square of cardboard taped to its edge. People of many ages pass tools and bowls between tables while a bicycle sits on a repair stand and someone fixes a toaster. Small groups talk while a few people stand apart with arms crossed. A figure in a weathered rain jacket holds a bowl at the edge of the crowd.',
  'cards/co-kit-01':
    'A medium view inside a cluttered repair co-op workshop at dusk. On the workbench, a large decorated kinetic wheel with painted ribbons on its rim spins on its own, spokes blurring. Kit, a Hmong American woman in her late twenties with short asymmetric black hair and paint-splattered coveralls covered in bright fabric patches, sits on a stool with arms folded and a conflicted look, an empty stool pulled out beside her. A teenage apprentice in a hoodie leans eagerly toward the wheel while a volunteer in a safety vest holds a clipboard by the door. A figure in a weathered rain jacket stands at the edge.',
  'cards/co-juniper-01':
    'A wide view of a bayside street after rain, where a concrete storm-drain culvert has been overgrown by a thick dam of lush green moss. Rainwater spills across the pavement and runs under the door of a small repair shop. The owner stands ankle-deep in rubber boots, holding up a paper estimate. Facing him is Juniper, a curvy young woman with messy auburn hair, a green ribbon and tiny ferns in it, freckles, a layered thrift-store sweater and a long patchwork skirt, looking sheepish. A figure in a weathered rain jacket stands in the puddle nearby.',
  'cards/co-cedar-01':
    'A medium view of an empty parking lot at night, wrapped in thick fog under sodium street lights. In the open driver door of an old pickup truck sits Cedar, a rugged man in his thirties of mixed Latino heritage with warm light brown skin, dark hair, short stubble, a worn trucker cap and an oil-stained canvas work jacket. His hand rests on the dial of a glowing CB radio under the dashboard, the hand microphone dangling on its coiled cord, and his face is troubled. A figure in a weathered rain jacket leans on the truck door.',
  'cards/co-mara-01':
    'Inside a borrowed downtown art studio with bare brick walls and a tall window, two pencil drawings hang side by side at eye level, pinned with tacks. Both show the same bird with six spread wings; the right-hand drawing has one extra dark pencil line across its left wing. Below them a paint-spattered worktable holds a phone lying face up with its screen glowing, a closed sketchbook, a jar of brushes and a white envelope stuffed with cash. A figure in a weathered rain jacket stands before the wall, seen from behind, looking from one drawing to the other. Gray afternoon light falls through the window onto the paper.',
  'cards/wh-003':
    'A medium view of a peach stand at a farmers market on a palm-lined town plaza. A vendor in a straw hat holds out a ripe peach toward a figure in a weathered rain jacket, seen from behind and reaching for it. Rows of woven baskets heaped with glowing golden peaches carry blank paper tags, and one basket sits apart on a crate. A blank chalk board stands at the front, and a teenager holds up a phone toward it. Around the stall hangs a faint shimmer of late-summer light, though the morning is gray with fog.',
  'cards/wh-012':
    'A wide view of a misty community forest where three redwood trunks bear small blank metal tags. Juniper, a curvy young woman with messy auburn hair, a green ribbon and tiny ferns in it, freckles, a layered thrift-store sweater and a long patchwork skirt, turns to look back thoughtfully. Beside her, a volunteer tree counter in a fleece vest holds a ledger and a snapped measuring tape, while a foundation officer in a clean jacket carries rolled fence plans. A small creek with muddy banks runs under a footbridge. A figure in a weathered rain jacket stands on the trail.',
  'cards/lx-fast-01':
    'A wide view of a palm-lined town plaza in a rush of festival setup, people blurring past. A fast-talking man in a striped vest sells corked glass bottles of swirling fog from a wooden cart, holding up one bottle with a small round glowing clock dial floating inside it, fog curling from its neck. Nearby, stagehands in black work clothes lean over a folding table comparing two blank contracts among road cases and half-built stage truss. A figure in a weathered rain jacket stands between the cart and the table, seen from behind.',
  'cards/wh-024':
    'A wide view of a beach at low tide with a large rocky sea stack and a creek mouth. On the wet sand stands a small kinetic sculpture made from driftwood and bicycle cable, perfectly still, while its long shadow dances on its own across the sand. Kit, a Hmong American woman in her late twenties with short asymmetric black hair and paint-splattered coveralls covered in bright patches, frowns at a contract. A sponsor in a puffer jacket waits with a clipboard as a photo crew sets up a reflector. A figure in a weathered rain jacket watches from behind.',
  'cards/wh-027':
    'A wide view of a small fishing harbor with a wooden pier, moored boats and a rocky headland in the mist. On an overturned crate stands a small gray gull, an ordinary bird with her beak wide open mid-shout, and a whole flock of gulls is gathered on the dock facing her. Beside the crate, a weary dockworker in orange bib overalls and a knit cap crouches and translates with one raised hand. Behind them, open lidless public trash cans overflow, and people on a bench hold their lunches close. A figure in a weathered rain jacket watches from behind.',
  'cards/lx-night-01':
    "A wide view of a gravel bar on a broad coastal river late at night, low fog drifting over fast water. On a rounded stone at the river's edge stands a tiny thumb-sized uniformed official, holding a miniature clipboard. Behind him a road crew in high-visibility vests sits wearily on a work truck tailgate beside a bent, mud-streaked blank warning board. Headlamps throw amber light across the stones. A figure in a weathered rain jacket crouches off to one side, seen from behind, listening.",
  'cards/wh-043':
    'Inside a cramped upstairs office in an old brick building on a Victorian waterfront street, a long folding table holds stacks of canvas festival tote bags and paper cups, each printed with the same black ink drawing of a bird with six spread wings. An open sketchbook lies at the near end of the table, showing the original pencil drawing of that bird. Three stage technicians in black work shirts stand around a squat fog machine on a hand cart, its nozzle pouring a low white cloud across the floor and over the tote bags. A promoter in a quilted vest holds up a phone. A figure in a weathered rain jacket stands at the end of the table, seen from behind. Gray daylight comes through tall sash windows.',
  'cards/wh-055':
    'A medium view of a wooden dock on a foggy bay. Cedar, a rugged man in his thirties with warm light brown skin, short stubble, a worn trucker cap and an oil-stained canvas work jacket, sits on an overturned crate holding a phone to his ear. In his other hand he turns over a dripping, barnacled radio transmitter. An open toolbox, a coil of antenna cable and a small creek sensor buoy lie on the wet planks beside him. A figure in a weathered rain jacket stands off to one side.',
  'cards/lx-heart-01':
    'A wide view of a redwood park at dusk, fog drifting between the tall trunks. A real peacock stands on a picnic table outside a small wooden workshop shed, tail feathers fanned, a tiny blank paper badge pinned to its chest. Park volunteers sit on folding chairs in pairs, talking quietly under string lights, one holding a blank clipboard. The open shed door shows a workbench and hand tools. A figure in a weathered rain jacket stands on the path off to one side, seen from behind.',
}

export const ECOTONE_STORYLINE_ART_PROMPTS: Partial<
  Record<EndingLine, string>
> = {
  mara: "A busy tattoo studio storefront on a small-town plaza with palm trees, a green lawn and old wooden two-floor buildings, on a bright morning with fog lifting off the rooftops. Through the big front window three young apprentices in black aprons work at their stations under jointed lamps, one shading a fern onto a client's forearm. A large painted mural of a bird with six spread wings covers the brick side wall of the building in deep blue and gold. A short line of customers waits on a bench out front holding coffee cups. A figure in a weathered rain jacket stands on the plaza lawn, seen from behind, looking up at the mural.",
}

export function ecotoneArtPrompt(asset: string | null | undefined) {
  if (!asset) return undefined
  return ECOTONE_CARD_ART_PROMPTS[asset] ?? MYSTERY_ART_PROMPTS[asset]
}
